  .ai-content p {
    font-size: 19px;
    color: #94a3b8;
    line-height: 1.6;
  }

  .ai-content .highlight-purple { color: #a78bfa; font-weight: 600; }
  .ai-content .highlight-blue { color: #3b82f6; font-weight: 600; }

  .ai-sub-stats {
    display: flex;
    gap: 40px;
    margin-top: 20px;
  }

  .ai-sub-stat {
    text-align: center;
