    font-size: 17px;
    color: #fbbf24;
    font-weight: 500;
    margin-top: 16px;
    border-radius: 0 8px 8px 0;
  }

  .ts-callout {
    background: rgba(59,130,246,0.1);
    border-left-color: #3b82f6;
    color: #60a5fa;
  }
</style>
